Here is the generated code to evaluate:

<!-- @FIGURE_UI_BEGIN -->
<p id="demoNarration" style="margin:0;font-size:10px;max-width:180px">With θ1 well below θc, the ray splits at the boundary: part refracts into n2 bent away from the normal, and part reflects back into n1.</p>
<div style="display:flex;gap:4px;align-items:center">
  <button onclick="prevStep()">◀</button><span id="stepLabel">1 / 5</span><button onclick="nextStep()">▶</button>
</div>
<label>Incident angle θ1 (°): <output id="incidentAngleVal">30</output>
  <input id="incidentAngleInput" type="range" min="0" max="89" step="1" value="30"
    oninput="document.getElementById('incidentAngleVal').value=this.value;update_incidentAngle(+this.value)"></label>
<label>Index ratio n2/n1: <output id="indexRatioVal">0.75</output>
  <input id="indexRatioInput" type="range" min="0.5" max="0.95" step="0.01" value="0.75"
    oninput="document.getElementById('indexRatioVal').value=this.value;update_indexRatio(+this.value)"></label>
<div id="readout" style="font-size:11px;line-height:1.5"></div>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
var W = 620, H = 420;
draw.viewbox(0, 0, W, H);

var PX = 300, PY = 210;           // point of incidence
var LR = 165;                      // ray length
var TEAL = '#0e7f8c';
var state = { theta1: 30, ratio: 0.75 };
var scene = draw.group();

function rad(d) { return d * Math.PI / 180; }
function deg(r) { return r * 180 / Math.PI; }

function arrowLine(g, x1, y1, x2, y2, color, width, dash, opacity) {
  var ln = g.line(x1, y1, x2, y2).stroke({ color: color, width: width, opacity: opacity });
  if (dash) ln.attr('stroke-dasharray', dash);
  // arrowhead at 60% along the ray
  var t = 0.62, ax = x1 + (x2 - x1) * t, ay = y1 + (y2 - y1) * t;
  var ang = Math.atan2(y2 - y1, x2 - x1), s = 7;
  var p1 = [ax, ay],
      p2 = [ax - s * Math.cos(ang - 0.42), ay - s * Math.sin(ang - 0.42)],
      p3 = [ax - s * Math.cos(ang + 0.42), ay - s * Math.sin(ang + 0.42)];
  g.polygon([p1, p2, p3].map(function (p) { return p.join(','); }).join(' '))
    .fill(color).opacity(opacity);
}

function arcLabel(g, cx, cy, r, a0, a1, label, lx, ly) {
  var pts = [];
  for (var i = 0; i <= 24; i++) {
    var a = a0 + (a1 - a0) * i / 24;
    pts.push([cx + r * Math.cos(a), cy + r * Math.sin(a)].join(','));
  }
  g.polyline(pts.join(' ')).fill('none').stroke({ color: '#333', width: 1 });
  g.plain(label).font({ size: 15, family: 'serif', style: 'italic' })
    .center(lx, ly).attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 3 });
}

function render() {
  scene.clear();
  var t1 = rad(state.theta1);
  var thetaC = deg(Math.asin(state.ratio));
  var sinT2 = Math.sin(t1) / state.ratio;
  var hasRefr = sinT2 <= 1;
  var t2 = hasRefr ? Math.asin(Math.min(1, sinT2)) : Math.PI / 2;
  var pastC = state.theta1 > thetaC + 0.5;
  var nearC = hasRefr && Math.abs(state.theta1 - thetaC) <= 1.2;

  // media
  scene.rect(W, PY).move(0, 0).fill('#ffffff');
  scene.rect(W, H - PY).move(0, PY).fill('#cfe3ee');
  scene.line(0, PY, W, PY).stroke({ color: '#7fa8bd', width: 1.5 });
  scene.plain('n₂').font({ size: 18, family: 'serif', style: 'italic' }).move(40, PY - 38);
  scene.plain('n₁').font({ size: 18, family: 'serif', style: 'italic' }).move(W - 50, PY + 40);

  // normal (dashed vertical)
  scene.line(PX, 20, PX, H - 20).stroke({ color: '#555', width: 1.2, dasharray: '6,5' });

  // endpoints
  var ix = PX - LR * Math.sin(t1), iy = PY + LR * Math.cos(t1);        // incident source (lower-left)
  var rx = PX + LR * Math.sin(t1), ry = PY + LR * Math.cos(t1);        // reflected (lower-right)
  var tx = PX + LR * Math.sin(t2), ty = PY - LR * Math.cos(t2);        // refracted (upper-right)
  var tc = rad(thetaC);
  var cx0 = PX - LR * Math.sin(tc), cy0 = PY + LR * Math.cos(tc);      // critical ref (lower-left dashed)

  // dashed critical-angle reference ray in n1
  arrowLine(scene, cx0, cy0, PX, PY, '#888', 1.4, '5,4', 0.9);

  // refracted ray: fades as θ1 → θc and beyond
  var refrOp = hasRefr ? Math.max(0.25, 1 - 0.75 * Math.pow(Math.sin(t1) / state.ratio, 4)) : 0;
  if (hasRefr && refrOp > 0.02) arrowLine(scene, PX, PY, tx, ty, TEAL, 2.5, null, refrOp);

  // incident + reflected
  arrowLine(scene, ix, iy, PX, PY, TEAL, 2.5, null, 1);
  arrowLine(scene, PX, PY, rx, ry, TEAL, 2.5, null, pastC ? 1 : 0.85);

  // labels
  scene.plain('Incident ray').font({ size: 12, family: 'sans-serif' })
    .move(ix - 10, iy - 34).attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 3 });
  scene.plain('Reflected ray').font({ size: 12, family: 'sans-serif' })
    .move(rx - 40, ry + 12).attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 3 });
  if (hasRefr && refrOp > 0.05 && !nearC) {
    scene.plain('Refracted ray').font({ size: 12, family: 'sans-serif' })
      .move(tx - 20, ty - 26).opacity(refrOp)
      .attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 3 });
  }

  // angle arcs (angles from the normal)
  var ar = 55;
  arcLabel(scene, PX, PY, ar, Math.PI / 2, Math.PI / 2 + t1, 'θ₁', PX - 24, PY + ar + 8);
  arcLabel(scene, PX, PY, ar, Math.PI / 2 - t1, Math.PI / 2, 'θ₁', PX + 24, PY + ar + 8);
  arcLabel(scene, PX, PY, ar + 18, Math.PI / 2, Math.PI / 2 + tc, 'θc', PX - 40, PY + ar + 26);
  if (hasRefr && !nearC) {
    arcLabel(scene, PX, PY, 45, -Math.PI / 2, -Math.PI / 2 + t2, 'θ₂', PX + 34, PY - 58);
  }

  // critical-angle special markers
  if (nearC) {
    var sq = 13;
    scene.polyline([PX, PY - sq, PX + sq, PY - sq, PX + sq, PY].join(' '))
      .fill('none').stroke({ color: '#333', width: 1.4 });
    scene.plain('θ₂ = 90°').font({ size: 14, family: 'serif' })
      .move(PX + 22, PY - 32).attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 3 });
  }
  if (pastC) {
    scene.plain('Total internal').font({ size: 14, family: 'sans-serif', weight: 'bold' })
      .fill('#b03030').center(PX + 95, PY + 70)
      .attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 3 });
    scene.plain('reflection').font({ size: 14, family: 'sans-serif', weight: 'bold' })
      .fill('#b03030').center(PX + 95, PY + 88)
      .attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 3 });
  }

  // numeric readout
  var ro = document.getElementById('readout');
  ro.innerHTML = 'θ₁ = ' + state.theta1.toFixed(0) + '°<br>' +
    'θc = arcsin(n₂/n₁) = ' + thetaC.toFixed(1) + '°<br>' +
    (hasRefr ? 'θ₂ = ' + deg(t2).toFixed(1) + '°'
             : 'θ₂ undefined — sin θ₂ = ' + sinT2.toFixed(2) + ' > 1');
}

function update_incidentAngle(v) { state.theta1 = v; render(); }
function update_indexRatio(v) { state.ratio = v; render(); }

// ── demo steps ──
var steps = [
  { title: 'Ordinary refraction', a: 30, r: 0.75,
    n: 'With θ1 well below θc, the ray splits at the boundary: part refracts into n2 bent away from the normal (θ2 > θ1), and part reflects back into n1 at the same angle θ1.' },
  { title: 'Approaching the critical angle', a: 45, r: 0.75,
    n: 'Drag θ1 toward the dashed θc reference ray: the refracted ray swings closer and closer to the surface as θ2 approaches 90°.' },
  { title: 'At the critical angle', a: 49, r: 0.75,
    n: 'At θ1 = θc the refracted ray runs flat along the interface (θ2 = 90°) — this defines the critical angle by sin(θc) = n2/n1.' },
  { title: 'Total internal reflection', a: 65, r: 0.75,
    n: 'Push θ1 past θc: the refracted ray disappears entirely and all light reflects back into n1 — the ray is trapped in the denser medium.' },
  { title: 'Dependence on the indices', a: 65, r: 0.60,
    n: 'Now slide n2/n1 downward: the dashed θc reference moves toward the normal, and total internal reflection begins at smaller angles — confinement depends only on the index ratio.' }
];
var stepIdx = 0;
function setStep(i) {
  stepIdx = Math.max(0, Math.min(steps.length - 1, i));
  var s = steps[stepIdx];
  var aIn = document.getElementById('incidentAngleInput');
  var rIn = document.getElementById('indexRatioInput');
  aIn.value = s.a; document.getElementById('incidentAngleVal').value = s.a;
  rIn.value = s.r; document.getElementById('indexRatioVal').value = s.r;
  update_incidentAngle(s.a); update_indexRatio(s.r);
  document.getElementById('demoNarration').textContent = s.n;
  document.getElementById('stepLabel').textContent = (stepIdx + 1) + ' / ' + steps.length;
}
function nextStep() { setStep(stepIdx + 1); }
function prevStep() { setStep(stepIdx - 1); }

setStep(0);
window.__markRendered();
// @FIGURE_CODE_END

Output ONLY the JSON evaluation object.

systemPrompt:
You are the orchestration agent for an iterative figure-generation loop. Generation works by taking an original static 2D figure, making a generation plan, generating an interactive 2D figure (SVG.js / Chart.js / Mermaid), and evaluating it.

You will receive the critic evaluation, including failure modes, scores, notes, and action items.
Your job is to decide which part of the system is most responsible for the problem:
- planner: the interaction plan or conceptual decomposition is wrong, incomplete, or missing the right elements
- generator: the plan is close to right, but the rendered implementation, labels, layout, interactivity, or execution is broken
