function deg(r) { return r * 180 / Math.PI; }
function haloText(g, str, x, y, size, color, weight, anchor) {
  return g.plain(str).font({ size: size, family: 'sans-serif', weight: weight || 'normal', anchor: anchor || 'start' })
    .fill(color || '#222').move(x, y)
    .attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 3, 'stroke-linejoin': 'round' });
}
function serifText(g, str, x, y, size, anchor) {
  return g.plain(str).font({ size: size, family: 'serif', style: 'italic', anchor: anchor || 'middle' })
    .fill('#111').center(x, y)
    .attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 3, 'stroke-linejoin': 'round' });
}
function arrowLine(g, x1, y1, x2, y2, color, width, dash, opacity, tip, popup) {
  var ln = g.line(x1, y1, x2, y2).stroke({ color: color, width: width, opacity: opacity, linecap: 'round' });
  if (dash) ln.attr('stroke-dasharray', dash);
  var t = 0.62, ax = x1 + (x2 - x1) * t, ay = y1 + (y2 - y1) * t;
  var ang = Math.atan2(y2 - y1, x2 - x1), s = 7;
  g.polygon([[ax, ay],
    [ax - s * Math.cos(ang - 0.42), ay - s * Math.sin(ang - 0.42)],
    [ax - s * Math.cos(ang + 0.42), ay - s * Math.sin(ang + 0.42)]])
    .fill(color).opacity(opacity);
  if (tip) {
    var hit = g.line(x1, y1, x2, y2).stroke({ color: '#000', width: 14, opacity: 0 }).css('cursor', 'pointer');
    hit.on('mousemove', function (e) { showTooltip(tip, e); })
       .on('mouseleave', function () { hideTooltip(); })
       .on('click', function () { showPopup(tip, popup); });
  }
}
function arcLabel(g, cx, cy, r, a0, a1, label, labelR) {
  var pts = [];
  for (var i = 0; i <= 24; i++) {
    var a = a0 + (a1 - a0) * i / 24;
    pts.push([cx + r * Math.cos(a), cy + r * Math.sin(a)]);
  }
  g.polyline(pts).fill('none').stroke({ color: '#333', width: 1 });
  var am = (a0 + a1) / 2, rr = labelR || (r + 15);
  serifText(g, label, cx + rr * Math.cos(am), cy + rr * Math.sin(am), 15);
}

function render() {
  scene.clear();
  var t1 = rad(state.theta1);
  var thetaC = deg(Math.asin(state.ratio));
  var sinT2 = Math.sin(t1) / state.ratio;
  var nearC = Math.abs(state.theta1 - thetaC) <= 1.3;
  var pastC = state.theta1 > thetaC + 1.3;
  var hasRefr = sinT2 <= 1 || nearC;
  var t2 = nearC ? Math.PI / 2 : (sinT2 <= 1 ? Math.asin(Math.max(-1, Math.min(1, sinT2))) : Math.PI / 2);

  // media and boundary
  scene.rect(W, PY).move(0, 0).fill('#ffffff');
  scene.rect(W, H - PY).move(0, PY).fill('#cfe3ee');
  scene.line(0, PY, W, PY).stroke({ color: '#7fa8bd', width: 1.5 });
  serifText(scene, 'n₂', 48, PY - 42, 20);
  serifText(scene, 'n₁', W - 52, PY + 58, 20);

  // normal
  scene.line(PX, 22, PX, H - 22).stroke({ color: '#555', width: 1.2 }).attr('stroke-dasharray', '6,5');

  // ray endpoints
  var ix = PX - LR * Math.sin(t1), iy = PY + LR * Math.cos(t1);
  var rx = PX + LR * Math.sin(t1), ry = PY + LR * Math.cos(t1);
  var tx = PX + LR * Math.sin(t2), ty = PY - LR * Math.cos(t2);
  var tc = rad(thetaC);
  var cx0 = PX - LR * Math.sin(tc), cy0 = PY + LR * Math.cos(tc);

  // refracted ray: full in ordinary refraction, fades only in the last few degrees, flat and full at θc
  var refrOp = 0;
  if (hasRefr) {
    if (nearC) refrOp = 1;
    else {
      var d = thetaC - state.theta1;
      refrOp = d > 4 ? 1 : Math.max(0.25, 0.35 + 0.65 * (d - 1.3) / (4 - 1.3));
    }
  }
  if (hasRefr && refrOp > 0.02) {
    arrowLine(scene, PX, PY, tx, ty, TEAL, 2.6, null, refrOp,
      'Refracted ray', 'Snell\'s law gives n1 sin(θ1) = n2 sin(θ2). Because n1 > n2 here, θ2 is larger than θ1 and the transmitted ray bends away from the normal.');
  }

  // dashed critical-angle reference only when at/above the critical configuration
  if (nearC || pastC) {
    arrowLine(scene, cx0, cy0, PX, PY, '#777', 1.5, '5,4', 0.95,
      'Critical-angle reference', 'The dashed ray marks θc = arcsin(n2/n1). Comparing the live incident ray with this reference shows when refraction can still exist.');
  }

  // incident and reflected rays
  arrowLine(scene, ix, iy, PX, PY, TEAL, 2.6, null, 1,
    'Incident ray', 'Light starts in the denser medium n1 and strikes the interface at angle θ1 measured from the dashed normal.');
  arrowLine(scene, PX, PY, rx, ry, TEAL, 2.6, null, pastC ? 1 : 0.9,
    'Reflected ray', 'Some light always reflects at the boundary. Beyond θc there is no transmitted solution, so the reflected ray carries all of the light back into n1.');

  // ray labels
  haloText(scene, 'Incident ray', ix - 8, iy - 34, 12);
  haloText(scene, 'Reflected ray', rx - 42, ry + 14, 12);
  if (hasRefr && refrOp > 0.05 && !nearC) haloText(scene, 'Refracted ray', tx - 18, ty - 28, 12);

  // de-cluttered angle arcs: incident/reflected θ1 use different radii; θc only when relevant
  arcLabel(scene, PX, PY, 44, Math.PI / 2, Math.PI / 2 + t1, 'θ₁', 60);
  arcLabel(scene, PX, PY, 68, Math.PI / 2 - t1, Math.PI / 2, 'θ₁', 84);
  if (nearC || pastC) arcLabel(scene, PX, PY, 96, Math.PI / 2, Math.PI / 2 + tc, 'θc', 112);
  if (hasRefr && !nearC) arcLabel(scene, PX, PY, 50, -Math.PI / 2, -Math.PI / 2 + t2, 'θ₂', 66);

  // critical-angle markers
  if (nearC) {
    var sq = 14;
    scene.polyline([[PX, PY - sq], [PX + sq, PY - sq], [PX + sq, PY]])
      .fill('none').stroke({ color: '#333', width: 1.4 });
    haloText(scene, 'θ₂ = 90°', PX + 24, PY - 36, 14, '#222', 'bold');
  }
  if (pastC) {
    haloText(scene, 'Total internal', PX + 78, PY + 58, 14, '#222', 'bold');
    haloText(scene, 'reflection', PX + 78, PY + 76, 14, '#222', 'bold');
  }

  // (a)/(b)/(c)-style caption tied to the current canonical configuration
  var cap = pastC ? '(c) Total internal reflection' : (nearC ? '(b) Critical angle' : '(a) Ordinary refraction');
  haloText(scene, cap, 18, H - 24, 13, '#333', 'bold');

  var ro = document.getElementById('readout');
  ro.innerHTML = 'θ₁ = ' + state.theta1.toFixed(0) + '°<br>' +
    'θc = arcsin(n₂/n₁) = ' + thetaC.toFixed(1) + '°<br>' +
    (nearC ? 'θ₂ = 90.0° — grazing the interface'
      : (sinT2 <= 1 ? 'θ₂ = ' + deg(t2).toFixed(1) + '°'
        : 'sin θ₂ = ' + sinT2.toFixed(2) + ' > 1: no real θ₂'));
}

function update_incidentAngle(v) { state.theta1 = v; render(); }
function update_indexRatio(v) { state.ratio = v; render(); }

var steps = [
  { a: 30, r: 0.75,
    n: 'With θ1 well below θc, the ray splits at the boundary: part refracts into n2 bent away from the normal (θ2 > θ1), and part reflects back into n1 at the same angle θ1.' },
  { a: 45, r: 0.75,
    n: 'Drag θ1 toward the critical angle: the refracted ray stays bright at first, then swings closer and closer to the surface as θ2 approaches 90°.' },
  { a: 49, r: 0.75,
    n: 'At θ1 = θc the refracted ray runs flat along the interface (θ2 = 90°) — this is panel (b) of the figure and defines the critical angle by sin(θc) = n2/n1.' },
  { a: 65, r: 0.75,
    n: 'Push θ1 past θc: the refracted ray disappears entirely and all light reflects back into n1 — the ray is trapped in the denser medium, exactly as in panel (c).' },
  { a: 65, r: 0.60,
    n: 'Now slide n2/n1 downward: the dashed θc reference moves toward the normal, and the onset of total internal reflection shifts to smaller angles — confinement depends only on the index ratio.' }
];
var stepIdx = 0;
function setStep(i) {
  stepIdx = Math.max(0, Math.min(steps.length - 1, i));
  var s = steps[stepIdx];
  var aIn = document.getElementById('incidentAngleInput');
  var rIn = document.getElementById('indexRatioInput');
  aIn.value = s.a; document.getElementById('incidentAngleVal').value = s.a;
  rIn.value = s.r; document.getElementById('indexRatioVal').value = s.r;
  update_incidentAngle(s.a); update_indexRatio(s.r);
  document.getElementById('demoNarration').textContent = s.n;
  document.getElementById('stepLabel').textContent = (stepIdx + 1) + ' / ' + steps.length;
}
function nextStep() { setStep(stepIdx + 1); }
function prevStep() { setStep(stepIdx - 1); }

setStep(0);
window.__markRendered();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

userContent.text:
Build an interactive figure using SVG.js.

CONCEPT: As the incident angle in a denser medium increases, the refracted ray bends away from the normal until it runs along the surface at the critical angle, beyond which light undergoes total internal reflection; the critical angle is set by sin(θc) = n2/n1.
KEY INSIGHT (what students should walk away understanding): Total internal reflection is simply refraction pushed past its geometric limit: once sin(θ1) exceeds n2/n1, Snell's law has no real solution for θ2, so no transmitted ray can exist.
DEMO STEPS: 5 guided steps — implement the step player in #ui

FULL BLUEPRINT:
{
  "concept": "As the incident angle in a denser medium increases, the refracted ray bends away from the normal until it runs along the surface at the critical angle, beyond which light undergoes total internal reflection; the critical angle is set by sin(θc) = n2/n1.",
  "figureType": "diagram",
  "elements": [
    "horizontal boundary line between two media",
    "lower medium n1, shaded light blue rectangle, labeled n1 at right edge",
    "upper medium n2, unshaded, labeled n2 at left",
    "vertical dashed normal line at the point of incidence",
    "incident ray (solid teal, arrow) traveling up to the boundary inside n1 at angle θ1 from the normal",
    "reflected ray (solid teal, arrow) returning into n1 at angle θ1 on the other side of the normal",
    "refracted ray (solid teal, arrow) in n2 bent away from the normal at angle θ2",
    "angle arc and label θ1 between incident ray and normal",
    "angle arc and label θ2 between refracted ray and normal",
    "dashed reference ray at the critical angle θc inside n1, with label θc",
    "right-angle square marker and label θ2 = 90° when the refracted ray runs along the interface",
    "annotation 'Total internal reflection' appearing when θ1 > θc"
  ],
  "interactions": [
    {
      "id": "incidentAngle",
      "type": "slider",
      "label": "Incident angle θ1 (°)",
      "range": [
        0,
        89,
        1
      ],
      "default": 30,
      "teaches": "Increasing θ1 bends the refracted ray ever farther from the normal until it skims the surface at θc and then vanishes — the learner sees total internal reflection as the continuous limit of refraction, not a separate phenomenon"
    },
    {
      "id": "indexRatio",
      "type": "slider",
      "label": "Index ratio n2/n1",
      "range": [
        0.5,
        0.95,
        0.01
      ],
      "default": 0.75,
      "teaches": "The critical angle depends only on the ratio of indices via sin(θc) = n2/n1 — lowering n2/n1 shrinks θc, so total internal reflection begins at smaller incident angles"
    }
  ],
  "demo_steps": [
    {
      "title": "Ordinary refraction",
      "narration": "With θ1 well below θc, the ray splits at the boundary: part refracts into n2 bent away from the normal (θ2 > θ1), and part reflects back into n1 at the same angle θ1.",
      "state": {
        "incidentAngle": 30,
        "indexRatio": 0.75
      }
    },
    {
      "title": "Approaching the critical angle",
      "narration": "Drag θ1 toward the dashed θc reference ray: the refracted ray swings closer and closer to the surface as θ2 approaches 90°.",
      "state": {
        "incidentAngle": 45,
        "indexRatio": 0.75
      }
    },
    {
      "title": "At the critical angle",
      "narration": "At θ1 = θc the refracted ray runs flat along the interface (θ2 = 90°) — this is panel (b) of the figure and defines the critical angle by sin(θc) = n2/n1.",
      "state": {
        "incidentAngle": 49,
        "indexRatio": 0.75
      }
    },
    {
      "title": "Total internal reflection",
      "narration": "Push θ1 past θc: the refracted ray disappears entirely and all light reflects back into n1 — the ray is trapped in the denser medium, exactly as in panel (c).",
      "state": {
        "incidentAngle": 65,
        "indexRatio": 0.75
      }
    },
    {
      "title": "Dependence on the indices",
      "narration": "Now slide n2/n1 downward: the dashed θc reference moves toward the normal, and the onset of total internal reflection shifts to smaller angles — confinement depends only on the index ratio.",
      "state": {
        "incidentAngle": 65,
        "indexRatio": 0.6
      }
    }
  ],
  "keyInsight": "Total internal reflection is simply refraction pushed past its geometric limit: once sin(θ1) exceeds n2/n1, Snell's law has no real solution for θ2, so no transmitted ray can exist.",
  "reconstructionNotes": "Single unified diagram (not three static panels) reproducing the shared visual language of the figure: light-blue shaded lower half labeled n1, white upper half labeled n2, vertical dashed normal at the incidence point, teal rays with arrowheads. Keep the dashed θc reference ray always visible inside n1, drawn at arcsin(n2/n1), so the learner can compare the live incident ray against it. Fade the refracted ray out smoothly as θ1 crosses θc and reveal the 'Total internal reflection' label near the reflected ray; show the right-angle square and 'θ2 = 90°' label when θ1 is within ~1° of θc. Read out current θ1, θ2, and θc numerically near the diagram. Refracted ray intensity can diminish as θ1 approaches θc to hint at energy shifting into the reflected ray."
}

